import { readFile, writeFile, mkdir, readdir } from 'node:fs/promises';
import { join } from 'node:path';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { callModel, disabledSkills, pool, skillContext, validateAuthor, measure } from '/Users/kosui/ghq/github.com/iwasa-kosui/nihongo-de-ok/.wt/codex/improve-document-headings/benchmarks/benchmark.mjs';
const root='/Users/kosui/ghq/github.com/iwasa-kosui/nihongo-de-ok/.wt/codex/improve-document-headings';
const out='/private/tmp/nihongo-staged-check-20260906';
const hash=s=>createHash('sha256').update(s).digest('hex');
const read=p=>readFile(p,'utf8');
const json=async p=>JSON.parse(await read(p));
const save=(p,v)=>writeFile(p,JSON.stringify(v,null,2)+'\n');
const [phase,...ids]=process.argv.slice(2);
if(!['init','outline','body'].includes(phase))throw Error('Use init, outline, or body');
for(const d of ['calls','outline','body','reviews','feedback'])await mkdir(join(out,d),{recursive:true});
const sources={};
for(const name of ['SKILL.md','references/delegation.md','references/japanese.md','references/document-types.md','references/document-shapes.md'])sources[name]=await read(join(root,name));
const sourceHashes=Object.fromEntries(Object.entries(sources).map(([n,s])=>[n,hash(s)]));
const allCases=await json(join(root,'benchmarks/cases.json'));
const cases=[];
for(const id of ['design-tradeoff','incident-record'])for(const repeat of [1,2])cases.push({...allCases.find(c=>c.id===id),caseId:id,id:`${id}.${repeat}`,repeat});
cases.push({...allCases.find(c=>c.id==='surgical-edit'),caseId:'surgical-edit',id:'surgical-edit.1',repeat:1});
cases.push({id:'short-comparison.1',caseId:'short-comparison',type:'stock',documentType:'機能仕様',prompt:'保存期間を比較できるように整理して。標準プランは30日、拡張プランは90日保存する。他の違いや仕様はない。',repeat:1});
cases.push({"id": "five-explanations.1", "caseId": "five-explanations", "type": "stock", "documentType": "操作/利用ガイド", "prompt": "各文は正しい。次の五つの説明を短い案内に整えて。\n\n- 保存ボタンを押すと値が保存される。\n- 保存後に画面が更新される。\n- 更新後は保存した値が表示される。\n- その値は画面を閉じても残る。\n- 次に開くと同じ値が表示される。", "repeat": 1});
const snapshotFile=join(out,'manifest.json');
if(phase==='init'){
  await save(snapshotFile,{createdAt:new Date().toISOString(),sourceRevision:execFileSync('git',['-C',root,'rev-parse','HEAD'],{encoding:'utf8'}).trim(),dirtySource:true,sourceHashes,model:'gpt-5.6-luna',effort:'low',jobs:2,codexVersion:execFileSync('codex',['--version'],{encoding:'utf8'}).trim(),note:'構成と本文の間に親の検査を挟む動作確認。比較ベンチマークとは別集計。'});
  await save(join(out,'skill-snapshot.json'),sources);
  await save(join(out,'requests.json'),cases.map(({id,caseId,type,prompt,repeat})=>({id,caseId,type,prompt,repeat})));
  console.log('initialized');process.exit(0);
}
const manifest=await json(snapshotFile);
if(JSON.stringify(manifest.sourceHashes)!==JSON.stringify(sourceHashes))throw Error('Skill changed since initialization');
const selected=ids.length?cases.filter(c=>ids.includes(c.id)):cases;
if(!selected.length||ids.some(id=>!cases.some(c=>c.id===id)))throw Error('Unknown case');
async function latest(dir,id){const files=(await readdir(join(out,dir))).filter(n=>n.startsWith(id+'.')&&n.endsWith('.json')).sort();return files.length?{name:files.at(-1),data:await json(join(out,dir,files.at(-1)))}:null;}
const outlineById={};
if(phase==='body')for(const c of selected){
  const outline=await latest('outline',c.id);
  if(!outline)throw Error(`${c.id}: no outline`);
  const approval=await json(join(out,'reviews',c.id+'.outline.json'));
  if(approval.status!=='pass'||approval.outlineHash!==hash(outline.data.response.body))throw Error(`${c.id}: outline has not passed current review`);
  outlineById[c.id]=outline.data.response.body;
}
const skills=await disabledSkills();
const schema=await json(join(root,'benchmarks/author.schema.json'));
await pool(selected,2,async c=>{
  const previous=await latest(phase,c.id);
  let attempt=0,feedback;
  if(previous){attempt=previous.data.attempt+1;if(attempt>1)throw Error(`${c.id}: stop for parent assessment before escalation`);feedback=await read(join(out,'feedback',c.id+'.'+phase+'.txt'));}
  const task=phase==='outline'
    ?'現在は構成の工程です。以下の原依頼に対する構成案だけをbodyへ返してください。本文はまだ執筆しません。各節の見出し候補（なしも可）、答える問い、含める情報と根拠を短く示し、構成のラダーで選んだ形をnotesへ記します。構成案を返したら親の判定を待って止めます。'
    :'現在は本文の工程です。親が検査して合格とした以下の構成に沿って、原依頼に対する本文をbodyへ返してください。各節の役割に適した本文のラダーを使い、選んだ形をnotesへ記します。構成の変更が必要なら、影響する部分をまだ書かず変更案をnotesへ返します。構成案や検査記録を本文に混ぜません。';
  const prompt=`日本語の文書作成を担当してください。次のスキルを適用します。委譲・ファイル操作は使わず、実行者自身で担当工程を処理してください。親は工程間と全文の意味を検査し、textlintは外部実行系が担当します。\n\n${skillContext(c,sources)}\n\n原依頼と原資料:\n${c.prompt}\n\n${task}`+(phase==='body'?`\n\n親が合格とした構成案:\n${outlineById[c.id]}`:'')+(previous?`\n\n前稿:\n${JSON.stringify(previous.data.response)}\n\n親の指摘:\n${feedback}`:'');
  const result=await callModel({model:'gpt-5.6-luna',effort:'low',prompt,schema,instructionFile:join(root,'benchmarks/author-instructions.txt'),prefix:join(out,'calls',`${c.id}.${phase}.${attempt}`),timeout:180,skills});
  validateAuthor(result.response);
  const path=join(out,phase,`${c.id}.${attempt}.md`);
  await writeFile(path,result.response.body);
  const record={id:c.id,phase,attempt,model:'gpt-5.6-luna',effort:'low',promptHash:hash(prompt),...(phase==='body'?{approvedOutlineHash:hash(outlineById[c.id])}:{}),...result};
  if(phase==='body')record.metrics=await measure(c,result.response,path);
  await save(join(out,phase,`${c.id}.${attempt}.json`),record);
  console.log(`${phase} ${c.id}: attempt ${attempt}, ${record.metrics?.lint.length??0} lint messages`);
});
